+  if (!result.is_empty()) {
+    MemTracker::record_virtual_memory_reserve(result.base(), result.size(), CALLER_PC, mem_tag);
+    log_debug(os, map)("Reserved placeholder memory " RANGEFMT, RANGEFMTARGS(result.base(), result.size()));
